
(function(){
'use strict';
const KEY='wai096_crm';
const DEFAULT_MAINT=[['MOT',12],['Service',12],['Major Service',24],['Brake Fluid Change',24],['Gearbox Oil Change',48],['Air Conditioning Gas',24],['Cambelt',60]];
const MAINT_ALIASES={'Brake Fluid':'Brake Fluid Change','Gearbox Oil':'Gearbox Oil Change','Air Conditioning':'Air Conditioning Gas'};
let db=load(), selectedId=null, activeTab='overview', crmMode='customers', prospectWindow=30, prospectView='pipeline';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(x&&x.customers){normaliseMaintenance(x);return x}}catch(e){}return {customers:[],communications:[],version:'WAI-115.34'} }
function normaliseMaintenance(data){(data.customers||[]).forEach(c=>(c.vehicles||[]).forEach(v=>{const old=v.maintenance||[];v.maintenance=DEFAULT_MAINT.map(([name,months])=>{const match=old.find(m=>(MAINT_ALIASES[m.name]||m.name)===name);return match?{...match,name,intervalMonths:Number(match.intervalMonths||months),applicable:name==='Cambelt'?(match.applicable!==false):true}:{id:id('MNT'),name,intervalMonths:months,lastDate:'',lastMileage:0,nextDueDate:'',nextDueMileage:0,applicable:name==='Cambelt'?true:true}})}));}
function save(){normaliseMaintenance(db);localStorage.setItem(KEY,JSON.stringify(db));document.dispatchEvent(new CustomEvent('wai096:crm-updated'));}
function invoiceTotals(inv){
  const total=(inv.lines||[]).reduce((sum,l)=>{
    const qty=Math.max(0,Number(l.qty||0)), sell=Math.max(0,Number(l.sell||0));
    const gross=qty*sell;
    const discount=String(l.discountType||'£')==='%'?gross*Math.max(0,Number(l.discount||0))/100:Math.max(0,Number(l.discount||0));
    const net=Math.max(0,gross-Math.min(discount,gross));
    const vat=net*Math.max(0,Number(l.vat||0))/100;
    return sum+net+vat;
  },0);
  return Math.round((total+Number.EPSILON)*100)/100;
}
function financeInvoices(){
  try{return JSON.parse(localStorage.getItem('wai0991Invoices')||'[]')||[]}catch{return[]}
}
function workshopJobsFromStore(){
  try{return JSON.parse(localStorage.getItem('workshopAIJobsV27')||'[]')||[]}catch{return[]}
}
function resolveInvoiceCustomerId(inv,jobsById){
  if(inv.crmCustomerId)return inv.crmCustomerId;
  const job=jobsById.get(inv.jobId);
  if(job?.customerId)return job.customerId;
  return '';
}
function syncFinancialsFromInvoices(){
  const invoices=financeInvoices(), jobsById=new Map(workshopJobsFromStore().map(j=>[j.id,j]));
  let changed=false;
  (db.customers||[]).forEach(c=>{
    if(c.financeLegacySpend==null){
      c.financeLegacySpend=Math.max(0,Number(c.lifetimeSpend||0));
      changed=true;
    }
    const linked=invoices.filter(inv=>resolveInvoiceCustomerId(inv,jobsById)===c.id);
    let issued=0,paid=0,outstanding=0,paidInvoices=0,lastSpendDate='';
    linked.forEach(inv=>{
      const total=invoiceTotals(inv);
      const status=String(inv.status||'');
      if(['Invoice Issued','Part Paid','Paid','Archived'].includes(status))issued+=total;
      if(status==='Paid'){
        paid+=total;
        paidInvoices++;
        const paidEvent=[...(inv.audit||[])].reverse().find(a=>String(a.action||'').toLowerCase()==='invoice marked paid');
        const paidDate=String(paidEvent?.at||inv.updatedAt||inv.date||'').slice(0,10);
        if(paidDate>lastSpendDate)lastSpendDate=paidDate;
      }else if(['Invoice Issued','Part Paid'].includes(status)){
        outstanding+=Math.max(0,total-Math.max(0,Number(inv.paidAmount||0)));
      }
    });
    const lifetimeInvoiced=Math.round((issued+Number.EPSILON)*100)/100;
    const lifetimeSpend=Math.round((Number(c.financeLegacySpend||0)+paid+Number.EPSILON)*100)/100;
    const outstandingBalance=Math.round((outstanding+Number.EPSILON)*100)/100;
    const averageInvoiceValue=paidInvoices?Math.round((paid/paidInvoices+Number.EPSILON)*100)/100:0;
    const next={lifetimeInvoiced,lifetimeSpend,outstandingBalance,paidInvoices,averageInvoiceValue,lastSpendDate};
    Object.entries(next).forEach(([k,v])=>{if(c[k]!==v){c[k]=v;changed=true}});
  });
  if(changed)save();
  return changed;
}

function id(prefix){return prefix+'-'+Date.now().toString(36).toUpperCase()+Math.random().toString(36).slice(2,5).toUpperCase()}
function normReg(v){return String(v||'').toUpperCase().replace(/[^A-Z0-9]/g,'')}
function displayReg(v){let r=normReg(v);return r.length>4?r.slice(0,-3)+' '+r.slice(-3):r}
function dateAddMonths(date,months){if(!date)return'';let d=new Date(date+'T12:00:00');d.setMonth(d.getMonth()+Number(months||0));return d.toISOString().slice(0,10)}
function daysUntil(date){if(!date)return null;return Math.ceil((new Date(date+'T23:59:59')-new Date())/86400000)}
function maintStatus(m){const d=daysUntil(m.nextDueDate);if(d===null)return 'amber';if(d<0)return 'red';if(d<=60)return 'amber';return 'green'}
function vehicleScore(v){let items=v.maintenance||[];if(!items.length)return 50;let total=0;items.forEach(m=>total+=maintStatus(m)==='green'?100:maintStatus(m)==='amber'?65:20);let score=total/items.length;let outstanding=(v.outstanding||[]).filter(x=>x.status!=='Completed'&&x.status!=='Declined').length;return Math.max(0,Math.round(score-outstanding*4))}
function customerHealth(c){let vs=(c.vehicles||[]).map(vehicleScore);let base=vs.length?vs.reduce((a,b)=>a+b,0)/vs.length:65;let contact=(c.mobile||c.home||c.work)&&c.email?5:0;let response=c.missedAppointments?Math.max(-15,-5*c.missedAppointments):5;let overdue=(c.vehicles||[]).flatMap(v=>v.outstanding||[]).filter(x=>x.status==='Outstanding').length;return Math.max(0,Math.min(100,Math.round(base+contact+response-overdue*3)))}
function loyalty(c){if(c.loyaltyOverride)return c.loyaltyOverride;let spend=Number(c.lifetimeSpend||0), visits=Number(c.visitCount||0), years=Math.max(0,(Date.now()-new Date(c.customerSince||Date.now()))/31557600000);if(spend>=5000||visits>=15||years>=7)return'Gold';if(spend>=1500||visits>=5||years>=2)return'Silver';return'Bronze'}
function customerName(c){return [c.title,c.firstName,c.surname].filter(Boolean).join(' ')||c.company||'Unnamed customer'}
function allJobs(){try{return typeof jobs!=='undefined'&&Array.isArray(jobs)?jobs:JSON.parse(localStorage.getItem('jobs')||'[]')}catch(e){return[]}}
function linkedJobs(v){return allJobs().filter(j=>normReg(j.reg)===normReg(v.registration)).sort((a,b)=>new Date(b.completedAt||b.createdAt)-new Date(a.completedAt||a.createdAt))}
function stats(){const cs=db.customers, vehicles=cs.flatMap(c=>c.vehicles||[]), due=vehicles.flatMap(v=>(v.maintenance||[]).filter(m=>m.applicable!==false&&maintStatus(m)!=='green')).length;return {customers:cs.length,vehicles:vehicles.length,due,health:cs.length?Math.round(cs.reduce((a,c)=>a+customerHealth(c),0)/cs.length):0}}
function render(){if(!$('crmScreen'))return;normaliseMaintenance(db);const st=stats();$('crmStats').innerHTML=[['Customers',st.customers],['Linked Vehicles',st.vehicles],['Maintenance Alerts',st.due],['Average Customer Health',st.health+'%']].map(x=>`<div class="stat-card"><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join('');const customerArea=$('crmCustomerArea'),prospectArea=$('crmProspectArea');if(customerArea)customerArea.classList.toggle('hidden',crmMode!=='customers');if(prospectArea)prospectArea.classList.toggle('hidden',crmMode!=='prospects');$('crmCustomersTab')?.classList.toggle('active',crmMode==='customers');$('crmProspectsTab')?.classList.toggle('active',crmMode==='prospects');if(crmMode==='prospects')renderProspectCentre();else{renderList();renderWorkspace();}}
function filtered(){let q=($('crmSearch')?.value||'').toLowerCase().replace(/\s/g,''), f=$('crmFilter')?.value||'all';return db.customers.filter(c=>{let text=[c.id,customerName(c),c.company,c.mobile,c.home,c.work,c.email,c.postcode,...(c.vehicles||[]).map(v=>v.registration)].join(' ').toLowerCase().replace(/\s/g,'');let ok=!q||text.includes(q);if(f==='active')ok=ok&&c.status!=='Inactive';if(f==='inactive')ok=ok&&c.status==='Inactive';if(f==='gold')ok=ok&&loyalty(c)==='Gold';if(f==='due')ok=ok&&(c.vehicles||[]).some(v=>(v.maintenance||[]).some(m=>maintStatus(m)!=='green'));return ok}).sort((a,b)=>customerName(a).localeCompare(customerName(b)))}
function renderList(){const list=filtered();$('crmResultCount').textContent=list.length+' result'+(list.length===1?'':'s');$('crmCustomerList').innerHTML=list.length?list.map(c=>`<div class="crm-customer-row ${selectedId===c.id?'active':''}" data-customer="${c.id}"><h3>${esc(customerName(c))}</h3><div class="crm-mini">${esc(c.id)} · ${esc(loyalty(c))} · Health ${customerHealth(c)}%</div><div class="crm-mini">${esc(c.mobile||c.home||c.email||'No contact details')} · ${(c.vehicles||[]).map(v=>displayReg(v.registration)).join(', ')||'No vehicles'}</div></div>`).join(''):'<p class="muted">No matching customers.</p>';document.querySelectorAll('[data-customer]').forEach(el=>el.onclick=()=>{selectedId=el.dataset.customer;activeTab='overview';render()})}
function renderWorkspace(){const c=db.customers.find(x=>x.id===selectedId);if(!c){$('crmWorkspace').innerHTML='<div class="card crm-empty"><h2>Select a customer</h2><p class="muted">Open a customer to view health, vehicles, maintenance, communications and history.</p></div>';return}let outstanding=(c.vehicles||[]).flatMap(v=>(v.outstanding||[]).filter(x=>x.status==='Outstanding'));$('crmWorkspace').innerHTML=`<div class="card"><div class="crm-profile-head"><div><span class="crm-eyebrow">${esc(c.id)}</span><h2>${esc(customerName(c))}</h2><p>${esc(c.address1||'')}${c.address1?', ':''}${esc(c.town||'')} ${esc(c.postcode||'')}</p><div class="crm-badges"><span class="crm-badge ${loyalty(c).toLowerCase()}">${loyalty(c)} customer</span>${(c.tags||[]).map(t=>`<span class="crm-badge">${esc(t)}</span>`).join('')}</div></div><div class="crm-profile-actions"><button class="primary crm-small-btn" id="crmCreateJobBtn">+ Book Workshop</button><button class="primary crm-small-btn" id="crmTextCustomerBtn">📱 Text Customer</button><button class="secondary crm-small-btn" id="crmSummaryBtn">Summarise Customer</button><button class="secondary crm-small-btn" id="crmEditBtn">Edit</button><button class="primary crm-small-btn" id="crmAddVehicleBtn">+ Vehicle</button></div></div><div class="crm-score-grid"><div class="crm-score-card"><span>Customer Health</span><strong>${customerHealth(c)}%</strong></div><div class="crm-score-card"><span>Loyalty</span><strong>${loyalty(c)}</strong></div><div class="crm-score-card"><span>Lifetime Invoiced</span><strong>£${Number(c.lifetimeInvoiced||0).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}</strong></div><div class="crm-score-card"><span>Lifetime Spend</span><strong>£${Number(c.lifetimeSpend||0).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}</strong></div><div class="crm-score-card"><span>Outstanding Balance</span><strong>£${Number(c.outstandingBalance||0).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}</strong></div><div class="crm-score-card"><span>Paid Invoices</span><strong>${Number(c.paidInvoices||0)}</strong></div><div class="crm-score-card"><span>Average Paid Invoice</span><strong>£${Number(c.averageInvoiceValue||0).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}</strong></div><div class="crm-score-card"><span>Outstanding Work</span><strong>£${outstanding.reduce((a,x)=>a+Number(x.value||0),0).toLocaleString('en-GB')}</strong></div></div><div class="crm-tabs">${[['overview','Overview'],['vehicles','Vehicles'],['maintenance','Maintenance'],['timeline','Timeline'],['communications','Communications'],['documents','Documents']].map(x=>`<button class="secondary ${activeTab===x[0]?'active':''}" data-crm-tab="${x[0]}">${x[1]}</button>`).join('')}</div><div id="crmTabBody"></div></div>`;document.querySelectorAll('[data-crm-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.crmTab;renderWorkspace()});$('crmCreateJobBtn').onclick=()=>startWorkshopJobFromCustomer(c);$('crmTextCustomerBtn').onclick=()=>textCRMCustomer(c);$('crmEditBtn').onclick=()=>openCustomerModal(c);$('crmAddVehicleBtn').onclick=()=>openVehicleModal(c);$('crmSummaryBtn').onclick=()=>showSummary(c);renderTab(c)}
function renderTab(c){let body=$('crmTabBody');if(activeTab==='overview'){let next=[];(c.vehicles||[]).forEach(v=>(v.maintenance||[]).filter(m=>m.applicable!==false).forEach(m=>next.push({reg:v.registration,...m,status:maintStatus(m)})));next.sort((a,b)=>{const ad=a.nextDueDate||'9999-12-31',bd=b.nextDueDate||'9999-12-31';const byDate=ad.localeCompare(bd);return byDate||String(a.name||'').localeCompare(String(b.name||''))});body.innerHTML=`<div class="crm-section-grid"><div><h3>Contact & Preferences</h3><p><strong>Mobile:</strong> ${esc(c.mobile||'Not entered')}</p><p><strong>Home:</strong> ${esc(c.home||'Not entered')}</p><p><strong>Work:</strong> ${esc(c.work||'Not entered')}</p><p><strong>Email:</strong> ${esc(c.email||'Not entered')}</p><p><strong>Preferred:</strong> ${esc(c.preferredContact||'Not set')} · ${esc(c.preferredTime||'Anytime')}</p><p><strong>Relationship:</strong> ${esc((c.preferences||[]).join(', ')||'No preferences recorded')}</p></div><div><h3>Next Conversation</h3>${next.map(x=>`<div class="crm-alert"><strong>${displayReg(x.reg)} · ${esc(x.name)}</strong><br>${x.nextDueDate?'Due '+new Date(x.nextDueDate+'T12:00:00').toLocaleDateString('en-GB'):'Due date missing'} · <span class="crm-status ${x.status}">${x.status.toUpperCase()}</span></div>`).join('')||'<p class="muted">No maintenance dates recorded.</p>'}${c.notes?`<div class="crm-note"><strong>Important note</strong><br>${esc(c.notes)}</div>`:''}</div></div><h3 class="crm-overview-maint-title">Vehicle Maintenance Due Dates</h3>${(c.vehicles||[]).map(v=>maintenanceOverview(v)).join('')||'<p class="muted">No vehicles linked.</p>'}`}
else if(activeTab==='vehicles'){body.innerHTML=(c.vehicles||[]).map(v=>vehicleCard(c,v)).join('')||'<p class="muted">No vehicles linked yet.</p>';document.querySelectorAll('[data-edit-vehicle]').forEach(b=>b.onclick=()=>openVehicleModal(c,c.vehicles.find(v=>v.id===b.dataset.editVehicle)));document.querySelectorAll('[data-delete-vehicle]').forEach(b=>b.onclick=()=>{if(confirm('Remove this vehicle from the CRM?')){c.vehicles=c.vehicles.filter(v=>v.id!==b.dataset.deleteVehicle);save();render()}})}
else if(activeTab==='maintenance'){let rows=(c.vehicles||[]).flatMap(v=>(v.maintenance||[]).filter(m=>m.applicable!==false).map(m=>({v,m})));body.innerHTML=`<h3>Vehicle Maintenance Centre</h3><table class="crm-due-table"><thead><tr><th>Vehicle</th><th>Item</th><th>Last completed</th><th>Next due</th><th>Mileage due</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(({v,m})=>`<tr><td>${displayReg(v.registration)}</td><td>${esc(m.name)}</td><td>${m.lastDate?new Date(m.lastDate).toLocaleDateString('en-GB'):'—'}</td><td>${m.nextDueDate?new Date(m.nextDueDate).toLocaleDateString('en-GB'):'—'}</td><td>${m.nextDueMileage||'—'}</td><td><span class="crm-status ${maintStatus(m)}">${maintStatus(m).toUpperCase()}</span></td><td><button class="secondary crm-small-btn" data-maint="${v.id}|${m.id}">Update</button></td></tr>`).join('')}</tbody></table>`;document.querySelectorAll('[data-maint]').forEach(b=>b.onclick=()=>{let [vid,mid]=b.dataset.maint.split('|'),v=c.vehicles.find(x=>x.id===vid),m=v.maintenance.find(x=>x.id===mid);openMaintenanceModal(c,v,m)})}
else if(activeTab==='timeline'){let events=[];(c.vehicles||[]).forEach(v=>{linkedJobs(v).forEach(j=>events.push({date:j.completedAt||j.createdAt,title:`${displayReg(v.registration)} · ${j.workRequired||j.status||'Workshop visit'}`,detail:`${j.technician||''} ${j.actualHours?`· ${Number(j.actualHours).toFixed(2)} hrs`:''}`}));(v.lifeStory||[]).forEach(e=>events.push(e))});(c.timeline||[]).forEach(e=>events.push(e));events.sort((a,b)=>new Date(b.date)-new Date(a.date));body.innerHTML=`<h3>Customer & Vehicle Life Story</h3>${events.map(e=>`<div class="crm-timeline-item"><strong>${new Date(e.date).toLocaleDateString('en-GB')} · ${esc(e.title)}</strong><p>${esc(e.detail||'')}</p></div>`).join('')||'<p class="muted">No timeline entries yet.</p>'}`}
else if(activeTab==='communications'){body.innerHTML=`<div class="crm-profile-head"><h3>Communication Timeline</h3><button class="primary crm-small-btn" id="crmAddComm">+ Add Contact</button></div>${(c.communications||[]).slice().reverse().map(x=>`<div class="crm-timeline-item"><strong>${new Date(x.date).toLocaleString('en-GB')} · ${esc(x.method)} · ${esc(x.outcome||'')}</strong><p>${esc(x.note)}</p></div>`).join('')||'<p class="muted">No contact recorded.</p>'}`;$('crmAddComm').onclick=()=>openCommunicationModal(c)}
else if(activeTab==='documents'){body.innerHTML=`<div class="crm-profile-head"><h3>Document Centre</h3><button class="primary crm-small-btn" id="crmAddDoc">+ Add Document Reference</button></div><p class="muted">Store references to invoices, estimates, VHCs, warranty documents, photos and service records.</p>${(c.documents||[]).map(d=>`<div class="crm-timeline-item"><strong>${esc(d.type)} · ${esc(d.name)}</strong><p>${esc(d.note||'')}</p></div>`).join('')||'<p class="muted">No documents recorded.</p>'}`;$('crmAddDoc').onclick=()=>openDocumentModal(c)} }
function vehicleCard(c,v){let jobs=linkedJobs(v), alerts=(v.maintenance||[]).filter(m=>maintStatus(m)!=='green').length;return `<div class="crm-vehicle-card"><div class="crm-vehicle-head"><div><div class="crm-reg">${displayReg(v.registration)}</div><h3>${esc(v.make)} ${esc(v.model)} ${esc(v.variant||'')}</h3><p class="crm-mini">${esc(v.id)} · VIN ${esc(v.vin||'Not entered')}</p></div><div><span class="crm-badge">Condition ${vehicleScore(v)}%</span><button class="primary crm-small-btn" onclick="window.WorkshopCRMBridge.loadNewJob('${c.id}','${v.id}')">Book Workshop</button><button class="secondary crm-small-btn" onclick="window.WorkshopCRMBridge.openMaintenance('${c.id}','${v.id}')">Maintenance Dates</button><button class="secondary crm-small-btn" data-edit-vehicle="${v.id}">Edit</button><button class="secondary crm-small-btn" data-delete-vehicle="${v.id}">Remove</button></div></div><div class="crm-vehicle-summary"><div><strong>${Number(v.mileage||0).toLocaleString('en-GB')}</strong><br><span class="crm-mini">Mileage</span></div><div><strong>${jobs.length}</strong><br><span class="crm-mini">Workshop visits</span></div><div><strong>${alerts}</strong><br><span class="crm-mini">Maintenance alerts</span></div></div><p><strong>Fuel:</strong> ${esc(v.fuel||'—')} · <strong>Transmission:</strong> ${esc(v.transmission||'—')} · <strong>Colour:</strong> ${esc(v.colour||'—')}</p></div>`}
function modal(html){let old=$('crmModal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<div id="crmModal" class="crm-modal"><div class="crm-modal-card">${html}</div></div>`);$('crmModal').onclick=e=>{if(e.target.id==='crmModal')e.currentTarget.remove()}}
function closeModal(){$('crmModal')?.remove()}
function field(label,id,value='',type='text',wide=false){return `<label class="${wide?'wide':''}">${label}<input id="${id}" type="${type}" value="${esc(value)}"></label>`}
function textCRMCustomer(c){
 const number=(c?.mobile||'').replace(/\s/g,'');
 if(!number){alert('No customer mobile number is recorded.');return}
 const first=c.firstName||customerName(c);
 const message=prompt('Text message to '+customerName(c)+':',`Hello ${first}, it is the Service Team. Please contact us if we can help with your vehicle.`);
 if(message===null)return;
 const body=String(message||'').trim();
 if(!body){alert('Please enter a message before sending.');return}
 const now=new Date().toISOString();
 c.communications=c.communications||[];
 c.communications.push({id:id('COM'),date:now,method:'Text',outcome:'Text opened',note:body});
 c.timeline=c.timeline||[];
 c.timeline.push({id:id('EVT'),date:now,type:'Communication',note:'Text message opened from CRM'});
 save();
 renderWorkspace();
 window.location.href=`sms:${encodeURIComponent(number)}?&body=${encodeURIComponent(body)}`;
}
function openCustomerModal(c){c=c||null;modal(`<div class="crm-modal-head"><h2>${c?'Edit':'New'} Customer</h2><button id="crmClose">×</button></div><div class="crm-field-grid">${field('Title','cfTitle',c?.title)}${field('First name','cfFirst',c?.firstName)}${field('Surname','cfSurname',c?.surname)}${field('Company','cfCompany',c?.company)}${field('Mobile','cfMobile',c?.mobile,'tel')}${field('Home telephone','cfHome',c?.home,'tel')}${field('Work telephone','cfWork',c?.work,'tel')}${field('Email','cfEmail',c?.email,'email')}${field('House name / number & street','cfAddress1',c?.address1,'text',true)}${field('Town / City','cfTown',c?.town)}${field('County','cfCounty',c?.county)}${field('Postcode','cfPostcode',c?.postcode)}<label>Preferred contact<select id="cfPreferred"><option>Mobile</option><option>Phone</option><option>Email</option><option>SMS</option><option>WhatsApp</option></select></label><label>Preferred time<select id="cfTime"><option>Anytime</option><option>Morning</option><option>Afternoon</option><option>Evening</option></select></label>${field('Customer since','cfSince',c?.customerSince||new Date().toISOString().slice(0,10),'date')}<div class="wide crm-auto-finance-note"><strong>Lifetime spend is automatic</strong><span>Paid invoices linked to this CRM customer update Lifetime Spend automatically. Issued invoices update Lifetime Invoiced.</span></div>${field('Tags (comma separated)','cfTags',(c?.tags||[]).join(', '),'text',true)}${field('Preferences (comma separated)','cfPrefs',(c?.preferences||[]).join(', '),'text',true)}<label class="wide">Important notes<textarea id="cfNotes">${esc(c?.notes||'')}</textarea></label></div><div class="crm-form-actions"><button class="secondary" id="crmCancel">Cancel</button><button class="primary" id="crmSaveCustomer">Save Customer</button></div>`);$('crmClose').onclick=$('crmCancel').onclick=closeModal;if(c){$('cfPreferred').value=c.preferredContact||'Mobile';$('cfTime').value=c.preferredTime||'Anytime'}$('crmSaveCustomer').onclick=()=>{let x=c||{id:id('CUS'),createdAt:new Date().toISOString(),vehicles:[],communications:[],documents:[],timeline:[],status:'Active',visitCount:0,missedAppointments:0};Object.assign(x,{title:$('cfTitle').value.trim(),firstName:$('cfFirst').value.trim(),surname:$('cfSurname').value.trim(),company:$('cfCompany').value.trim(),mobile:$('cfMobile').value.trim(),home:$('cfHome').value.trim(),work:$('cfWork').value.trim(),email:$('cfEmail').value.trim(),address1:$('cfAddress1').value.trim(),town:$('cfTown').value.trim(),county:$('cfCounty').value.trim(),postcode:$('cfPostcode').value.toUpperCase().trim(),preferredContact:$('cfPreferred').value,preferredTime:$('cfTime').value,customerSince:$('cfSince').value,tags:$('cfTags').value.split(',').map(x=>x.trim()).filter(Boolean),preferences:$('cfPrefs').value.split(',').map(x=>x.trim()).filter(Boolean),notes:$('cfNotes').value.trim()});if(!c)db.customers.push(x);selectedId=x.id;save();closeModal();render()}}
function defaultMaintenance(){return DEFAULT_MAINT.map(([name,months])=>({id:id('MNT'),name,intervalMonths:months,lastDate:'',lastMileage:'',nextDueDate:'',nextDueMileage:''}))}
function openVehicleModal(c,v){v=v||null;modal(`<div class="crm-modal-head"><h2>${v?'Edit':'Add'} Vehicle</h2><button id="crmClose">×</button></div><div class="crm-field-grid">${field('Registration','vfReg',v?.registration)}${field('VIN','vfVin',v?.vin)}${field('Make','vfMake',v?.make)}${field('Model','vfModel',v?.model)}${field('Variant','vfVariant',v?.variant)}${field('Year','vfYear',v?.year,'number')}${field('Colour','vfColour',v?.colour)}${field('Fuel','vfFuel',v?.fuel)}${field('Engine','vfEngine',v?.engine)}${field('Transmission','vfTrans',v?.transmission)}${field('Mileage','vfMileage',v?.mileage,'number')}${field('Date acquired','vfAcquired',v?.dateAcquired,'date')}${field('Warranty expiry','vfWarranty',v?.warrantyExpiry,'date')}</div><p class="muted">A complete maintenance schedule, including brake fluid every two years, will be created automatically for new vehicles.</p><div class="crm-form-actions"><button class="secondary" id="crmCancel">Cancel</button><button class="primary" id="crmSaveVehicle">Save Vehicle</button></div>`);$('crmClose').onclick=$('crmCancel').onclick=closeModal;$('vfReg').oninput=e=>e.target.value=e.target.value.toUpperCase();$('crmSaveVehicle').onclick=()=>{let reg=normReg($('vfReg').value);if(!reg){alert('Enter a registration');return}let duplicate=db.customers.flatMap(x=>(x.vehicles||[]).map(y=>({c:x,v:y}))).find(x=>normReg(x.v.registration)===reg&&x.v.id!==v?.id);if(duplicate&&!confirm(`This registration is already linked to ${customerName(duplicate.c)}. Add anyway?`))return;let x=v||{id:id('VEH'),maintenance:defaultMaintenance(),lifeStory:[],outstanding:[]};Object.assign(x,{registration:reg,vin:$('vfVin').value.toUpperCase().trim(),make:$('vfMake').value.trim(),model:$('vfModel').value.trim(),variant:$('vfVariant').value.trim(),year:$('vfYear').value,colour:$('vfColour').value.trim(),fuel:$('vfFuel').value.trim(),engine:$('vfEngine').value.trim(),transmission:$('vfTrans').value.trim(),mileage:Number($('vfMileage').value||0),dateAcquired:$('vfAcquired').value,warrantyExpiry:$('vfWarranty').value});if(!v)c.vehicles.push(x);save();closeModal();activeTab='vehicles';render()}}
function openMaintenanceModal(c,v,m){modal(`<div class="crm-modal-head"><h2>${displayReg(v.registration)} · ${esc(m.name)}</h2><button id="crmClose">×</button></div><div class="crm-field-grid">${field('Last completed date','mfLast',m.lastDate,'date')}${field('Last completed mileage','mfMileage',m.lastMileage,'number')}${field('Interval (months)','mfInterval',m.intervalMonths,'number')}${field('Next due date','mfNext',m.nextDueDate,'date')}${field('Next due mileage','mfNextMileage',m.nextDueMileage,'number')}${m.name==='Cambelt'?`<label class="wide crm-check"><input id="mfApplicable" type="checkbox" ${m.applicable!==false?'checked':''}> Cambelt applies to this vehicle</label>`:''}</div><div class="crm-form-actions"><button class="secondary" id="crmCancel">Cancel</button><button class="primary" id="crmSaveMaint">Save Maintenance</button></div>`);$('crmClose').onclick=$('crmCancel').onclick=closeModal;$('mfLast').onchange=()=>{if($('mfLast').value)$('mfNext').value=dateAddMonths($('mfLast').value,$('mfInterval').value)};$('mfInterval').onchange=()=>{if($('mfLast').value)$('mfNext').value=dateAddMonths($('mfLast').value,$('mfInterval').value)};$('crmSaveMaint').onclick=()=>{Object.assign(m,{lastDate:$('mfLast').value,lastMileage:Number($('mfMileage').value||0),intervalMonths:Number($('mfInterval').value||0),nextDueDate:$('mfNext').value,nextDueMileage:Number($('mfNextMileage').value||0),applicable:m.name==='Cambelt'?$('mfApplicable').checked:true});if(m.lastDate)v.lifeStory.push({date:m.lastDate,title:m.name+' completed',detail:`Recorded at ${Number(m.lastMileage||0).toLocaleString('en-GB')} miles`});save();closeModal();render()}}
function openCommunicationModal(c){modal(`<div class="crm-modal-head"><h2>Add Customer Contact</h2><button id="crmClose">×</button></div><div class="crm-field-grid"><label>Method<select id="coMethod"><option>Phone</option><option>Mobile</option><option>Email</option><option>SMS</option><option>WhatsApp</option><option>Letter</option><option>In person</option></select></label><label>Outcome<select id="coOutcome"><option>Spoke to customer</option><option>Message left</option><option>Booked</option><option>Declined</option><option>Awaiting response</option></select></label><label class="wide">Notes<textarea id="coNote"></textarea></label></div><div class="crm-form-actions"><button class="secondary" id="crmCancel">Cancel</button><button class="primary" id="crmSaveComm">Save Contact</button></div>`);$('crmClose').onclick=$('crmCancel').onclick=closeModal;$('crmSaveComm').onclick=()=>{c.communications=c.communications||[];c.communications.push({id:id('COM'),date:new Date().toISOString(),method:$('coMethod').value,outcome:$('coOutcome').value,note:$('coNote').value});save();closeModal();render()}}
function openDocumentModal(c){modal(`<div class="crm-modal-head"><h2>Add Document Reference</h2><button id="crmClose">×</button></div><div class="crm-field-grid"><label>Type<select id="doType"><option>Invoice</option><option>Estimate</option><option>VHC</option><option>Warranty</option><option>Photo</option><option>Service record</option><option>Correspondence</option></select></label>${field('Document name / reference','doName','') }<label class="wide">Notes<textarea id="doNote"></textarea></label></div><div class="crm-form-actions"><button class="secondary" id="crmCancel">Cancel</button><button class="primary" id="crmSaveDoc">Save Reference</button></div>`);$('crmClose').onclick=$('crmCancel').onclick=closeModal;$('crmSaveDoc').onclick=()=>{c.documents=c.documents||[];c.documents.push({id:id('DOC'),date:new Date().toISOString(),type:$('doType').value,name:$('doName').value,note:$('doNote').value});save();closeModal();render()}}
function showSummary(c){let due=(c.vehicles||[]).flatMap(v=>(v.maintenance||[]).filter(m=>maintStatus(m)!=='green').map(m=>`${displayReg(v.registration)}: ${m.name} ${m.nextDueDate?'due '+new Date(m.nextDueDate).toLocaleDateString('en-GB'):'date required'}`));modal(`<div class="crm-modal-head"><h2>Customer Summary</h2><button id="crmClose">×</button></div><div class="crm-note"><strong>${esc(customerName(c))}</strong> has been a customer since ${c.customerSince?new Date(c.customerSince).toLocaleDateString('en-GB'):'an unknown date'}. They have ${(c.vehicles||[]).length} linked vehicle(s), a Customer Health Score of ${customerHealth(c)}%, ${loyalty(c)} loyalty status and lifetime invoiced of £${Number(c.lifetimeInvoiced||0).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}, paid lifetime spend of £${Number(c.lifetimeSpend||0).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}, and an outstanding invoice balance of £${Number(c.outstandingBalance||0).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}. Preferred contact is ${esc(c.preferredContact||'not set')} ${c.preferredTime?'in the '+esc(c.preferredTime.toLowerCase()):''}.</div><h3>Next conversation</h3>${due.slice(0,8).map(x=>`<div class="crm-alert">${esc(x)}</div>`).join('')||'<p>No maintenance alerts.</p>'}${c.notes?`<h3>Important notes</h3><p>${esc(c.notes)}</p>`:''}`);$('crmClose').onclick=closeModal}
function dataIntegrity(){let issues=[];db.customers.forEach(c=>{if(!c.mobile&&!c.home&&!c.work)issues.push([c.id,'Missing telephone number']);if(!c.email)issues.push([c.id,'Missing email address']);if(!c.postcode)issues.push([c.id,'Missing postcode']);if(!(c.vehicles||[]).length)issues.push([c.id,'No vehicle linked']);(c.vehicles||[]).forEach(v=>{if(!v.vin)issues.push([displayReg(v.registration),'Missing VIN']);(v.maintenance||[]).forEach(m=>{if(!m.nextDueDate)issues.push([displayReg(v.registration),`${m.name}: next due date missing`])})})});let regs={};db.customers.forEach(c=>(c.vehicles||[]).forEach(v=>{let r=normReg(v.registration);regs[r]=(regs[r]||[]).concat(customerName(c))}));Object.entries(regs).filter(x=>x[1].length>1).forEach(([r,n])=>issues.push([displayReg(r),'Duplicate registration linked to '+n.join(', ')]));let names={};db.customers.forEach(c=>{let n=(customerName(c)+'|'+(c.postcode||'')).toLowerCase();names[n]=(names[n]||[]).concat(c.id)});Object.entries(names).filter(x=>x[1].length>1).forEach(([n,ids])=>issues.push([ids.join(', '),'Possible duplicate customers']));modal(`<div class="crm-modal-head"><h2>CRM Data Integrity Centre</h2><button id="crmClose">×</button></div><p class="muted">Finds incomplete or potentially duplicated records without changing workshop data.</p><div class="stats"><div class="stat-card"><strong>${issues.length}</strong><span>Issues found</span></div><div class="stat-card"><strong>${db.customers.length}</strong><span>Customers checked</span></div></div>${issues.map(x=>`<div class="crm-integrity-item"><strong>${esc(x[0])}</strong><span>${esc(x[1])}</span></div>`).join('')||'<div class="crm-note">No data integrity issues found.</div>'}`);$('crmClose').onclick=closeModal}


function maintenanceOverview(v){return `<div class="crm-maint-overview"><div class="crm-maint-overview-head"><strong>${displayReg(v.registration)} · ${esc(v.make||'')} ${esc(v.model||'')}</strong><button class="secondary crm-small-btn" onclick="window.WorkshopCRMBridge.openMaintenanceForVehicle('${v.id}')">Update dates</button></div><div class="crm-maint-overview-grid">${(v.maintenance||[]).map(m=>`<div class="crm-maint-tile ${m.applicable===false?'not-applicable':maintStatus(m)}"><span>${esc(m.name)}</span><strong>${m.applicable===false?'Not applicable':m.nextDueDate?new Date(m.nextDueDate+'T12:00:00').toLocaleDateString('en-GB'):'Date required'}</strong>${m.applicable!==false&&m.nextDueMileage?`<small>${Number(m.nextDueMileage).toLocaleString('en-GB')} miles</small>`:''}</div>`).join('')}</div></div>`}
function prospectKey(v,m){return `${v.id}|${m.id}`}
function prospectStatus(c,v,m){const s=(c.prospectContacts||{})[prospectKey(v,m)]||{};return {status:'Not contacted',contacted:false,responded:false,booked:false,completed:false,declined:false,snoozed:false,contactMethod:'',contactedAt:'',respondedAt:'',bookingDate:'',bookingValue:0,bookedAt:'',completedAt:'',invoiceValue:0,grossProfit:0,staff:'',snoozeUntil:'',timeline:[],...s}}
function prospectOwner(){return localStorage.getItem('wai1027_prospect_staff')||'Service Advisor'}
function setProspectOwner(){const v=prompt('Staff member handling prospecting:',prospectOwner());if(v&&v.trim()){localStorage.setItem('wai1027_prospect_staff',v.trim());renderProspectCentre()}}
function allProspects(days){let rows=[];(db.customers||[]).forEach(c=>(c.vehicles||[]).forEach(v=>(v.maintenance||[]).forEach(m=>{if(m.applicable===false||!m.nextDueDate)return;const d=daysUntil(m.nextDueDate),st=prospectStatus(c,v,m);if(st.declined||st.completed||st.removed)return;if(d!==null&&d<=days&&(!st.snoozed||!st.snoozeUntil||daysUntil(st.snoozeUntil)<=0))rows.push({c,v,m,days:d,status:st})})));return rows.sort((a,b)=>a.m.nextDueDate.localeCompare(b.m.nextDueDate))}
function addProspectTimeline(st,type,note,extra={}){st.timeline=Array.isArray(st.timeline)?st.timeline:[];st.timeline.unshift({id:id('PLOG'),date:new Date().toISOString(),type,note,staff:extra.staff||st.staff||prospectOwner(),...extra});return st}
function saveProspectStatus(c,v,m,patch,eventType,eventNote){const key=prospectKey(v,m);c.prospectContacts=c.prospectContacts||{};let current=prospectStatus(c,v,m);current={...current,...patch,updatedAt:new Date().toISOString()};if(eventType)addProspectTimeline(current,eventType,eventNote||eventType);c.prospectContacts[key]=current;save();renderProspectCentre()}
function prospectMessage(c,v,m){return `Hello ${c.firstName||customerName(c)}, our records show the ${m.name.toLowerCase()} for ${displayReg(v.registration)} is due ${m.nextDueDate?'on '+new Date(m.nextDueDate+'T12:00:00').toLocaleDateString('en-GB'):'soon'}. Please contact us if you would like us to arrange a booking.`}
function logProspectContact(c,v,m,method){const now=new Date().toISOString(),staff=prospectOwner();saveProspectStatus(c,v,m,{status:'Contacted',contacted:true,contactMethod:method,contactedAt:now,lastContactAt:now,staff},'Contacted',`${method} contact recorded`);c.communications=c.communications||[];c.communications.push({id:id('COM'),date:now,method,outcome:'Prospect reminder opened',note:prospectMessage(c,v,m)});save()}
function callProspect(cid,vid,mid){const c=db.customers.find(x=>x.id===cid),v=c?.vehicles?.find(x=>x.id===vid),m=v?.maintenance?.find(x=>x.id===mid);if(!c||!v||!m)return;const number=(c.mobile||c.home||c.work||'').replace(/\s/g,'');if(!number){alert('No customer telephone number is recorded.');return}logProspectContact(c,v,m,'Call');window.location.href=`tel:${encodeURIComponent(number)}`}
function sendProspectSMS(cid,vid,mid){const c=db.customers.find(x=>x.id===cid),v=c?.vehicles?.find(x=>x.id===vid),m=v?.maintenance?.find(x=>x.id===mid);if(!c||!v||!m)return;const number=(c.mobile||'').replace(/\s/g,'');if(!number){alert('No customer mobile number is recorded.');return}logProspectContact(c,v,m,'Text');window.location.href=`sms:${encodeURIComponent(number)}?&body=${encodeURIComponent(prospectMessage(c,v,m))}`}
function sendProspectEmail(cid,vid,mid){const c=db.customers.find(x=>x.id===cid),v=c?.vehicles?.find(x=>x.id===vid),m=v?.maintenance?.find(x=>x.id===mid);if(!c||!v||!m)return;if(!c.email){alert('No customer email address is recorded.');return}logProspectContact(c,v,m,'Email');const subject=`Maintenance reminder for ${displayReg(v.registration)} – ${m.name}`;window.location.href=`mailto:${encodeURIComponent(c.email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(prospectMessage(c,v,m))}`}
function toggleProspectContacted(cid,vid,mid,checked){const c=db.customers.find(x=>x.id===cid),v=c?.vehicles?.find(x=>x.id===vid),m=v?.maintenance?.find(x=>x.id===mid);if(!c||!v||!m)return;saveProspectStatus(c,v,m,{contacted:checked,status:checked?'Contacted':'Not contacted',contactedAt:checked?new Date().toISOString():'',staff:prospectOwner()},checked?'Contacted':'Reopened',checked?'Marked as contacted':'Contact status cleared')}
function markProspectResponded(cid,vid,mid){const c=db.customers.find(x=>x.id===cid),v=c?.vehicles?.find(x=>x.id===vid),m=v?.maintenance?.find(x=>x.id===mid);if(!c||!v||!m)return;saveProspectStatus(c,v,m,{contacted:true,responded:true,status:'Responded',respondedAt:new Date().toISOString(),staff:prospectOwner()},'Responded','Customer response confirmed')}
function markProspectBooked(cid,vid,mid){const c=db.customers.find(x=>x.id===cid),v=c?.vehicles?.find(x=>x.id===vid),m=v?.maintenance?.find(x=>x.id===mid);if(!c||!v||!m)return;const current=prospectStatus(c,v,m);const date=prompt('Booking date (YYYY-MM-DD):',current.bookingDate||new Date().toISOString().slice(0,10));if(!date)return;const valueRaw=prompt('Estimated booking value (£, ex VAT):',current.bookingValue||'0');const value=Math.max(0,Number(valueRaw||0));saveProspectStatus(c,v,m,{contacted:true,responded:true,booked:true,completed:false,declined:false,snoozed:false,status:'Booked',bookingDate:date,bookingValue:value,bookedAt:new Date().toISOString(),staff:prospectOwner()},'Booked',`Booked for ${date} · ${money(value)}`)}
function bookProspectIntoDiary(cid,vid,mid){markProspectBooked(cid,vid,mid);const c=db.customers.find(x=>x.id===cid),v=c?.vehicles?.find(x=>x.id===vid),m=v?.maintenance?.find(x=>x.id===mid);if(!c||!v||!m)return;if(typeof window.show==='function')window.show('diaryScreen');const set=(id,value)=>{const e=document.getElementById(id);if(e)e.value=value??''};set('reg',displayReg(v.registration));set('customer',customerName(c));set('phone',c.mobile||c.home||c.work||'');set('jobDescription',m.name);set('description',m.name);document.getElementById('diaryScreen')?.scrollIntoView({behavior:'smooth',block:'start'})}
function markProspectCompleted(cid,vid,mid){const c=db.customers.find(x=>x.id===cid),v=c?.vehicles?.find(x=>x.id===vid),m=v?.maintenance?.find(x=>x.id===mid);if(!c||!v||!m)return;const st=prospectStatus(c,v,m);const invoice=Number(prompt('Completed invoice value (£, ex VAT):',st.invoiceValue||st.bookingValue||0)||0);const gp=Number(prompt('Operational gross profit (£):',st.grossProfit||0)||0);saveProspectStatus(c,v,m,{contacted:true,responded:true,booked:true,completed:true,status:'Completed',completedAt:new Date().toISOString(),invoiceValue:Math.max(0,invoice),grossProfit:Math.max(0,gp),staff:st.staff||prospectOwner()},'Completed',`Job completed · Invoice ${money(invoice)} · GP ${money(gp)}`)}
function markProspectDeclined(cid,vid,mid){const c=db.customers.find(x=>x.id===cid),v=c?.vehicles?.find(x=>x.id===vid),m=v?.maintenance?.find(x=>x.id===mid);if(!c||!v||!m)return;const reason=prompt('Reason declined (optional):','');saveProspectStatus(c,v,m,{contacted:true,booked:false,declined:true,snoozed:false,status:'Declined',declinedAt:new Date().toISOString(),declineReason:reason||'',staff:prospectOwner()},'Declined',reason?`Declined · ${reason}`:'Customer declined')}
function snoozeProspect(cid,vid,mid){const c=db.customers.find(x=>x.id===cid),v=c?.vehicles?.find(x=>x.id===vid),m=v?.maintenance?.find(x=>x.id===mid);if(!c||!v||!m)return;const d=prompt('Snooze until (YYYY-MM-DD):',new Date(Date.now()+7*86400000).toISOString().slice(0,10));if(!d)return;saveProspectStatus(c,v,m,{snoozed:true,snoozeUntil:d,status:'Snoozed',staff:prospectOwner()},'Snoozed',`Snoozed until ${d}`)}
function allProspectRecords(){let rows=[];(db.customers||[]).forEach(c=>(c.vehicles||[]).forEach(v=>(v.maintenance||[]).forEach(m=>{const st=prospectStatus(c,v,m);if(st.contacted||st.responded||st.booked||st.completed||st.declined||st.snoozed)rows.push({c,v,m,st})})));return rows}
function prospectBookings(){return allProspectRecords().filter(x=>x.st.booked).sort((a,b)=>String(b.st.bookingDate||b.st.bookedAt||'').localeCompare(String(a.st.bookingDate||a.st.bookedAt||'')))}
function money(v){return '£'+Number(v||0).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}
function pct(a,b){return b?Math.round(a/b*100):0}
function prospectMetrics(){const rows=allProspectRecords(),contacted=rows.filter(x=>x.st.contacted),responded=rows.filter(x=>x.st.responded),booked=rows.filter(x=>x.st.booked),completed=rows.filter(x=>x.st.completed);return {rows,contacted,responded,booked,completed,declined:rows.filter(x=>x.st.declined),pipeline:booked.filter(x=>!x.st.completed).reduce((a,x)=>a+Number(x.st.bookingValue||0),0),bookingValue:booked.reduce((a,x)=>a+Number(x.st.bookingValue||0),0),invoiceValue:completed.reduce((a,x)=>a+Number(x.st.invoiceValue||0),0),gp:completed.reduce((a,x)=>a+Number(x.st.grossProfit||0),0)}}
function renderProspectTimeline(st){const t=Array.isArray(st.timeline)?st.timeline:[];return `<div class="crm-pro-timeline">${t.map(x=>`<div class="crm-pro-timeline-item"><span>${new Date(x.date).toLocaleString('en-GB')}</span><strong>${esc(x.type)}</strong><p>${esc(x.note||'')}</p><small>${esc(x.staff||'')}</small></div>`).join('')||'<p class="muted">No activity recorded yet.</p>'}</div>`}
function declinedProspects(){return allProspectRecords().filter(x=>x.st.declined).sort((a,b)=>String(b.st.declinedAt||b.st.updatedAt||'').localeCompare(String(a.st.declinedAt||a.st.updatedAt||'')))}
function deleteDeclinedProspect(cid,vid,mid){
 const c=db.customers.find(x=>x.id===cid),v=c?.vehicles?.find(x=>x.id===vid),m=v?.maintenance?.find(x=>x.id===mid);if(!c||!v||!m)return;
 if(!confirm(`Remove ${customerName(c)} · ${displayReg(v.registration)} from the Declined list?\n\nThe CRM customer and vehicle will remain, but this maintenance prospect will no longer appear in the active or declined prospect lists.`))return;
 const key=prospectKey(v,m);
 c.prospectContacts=c.prospectContacts||{};
 const current=prospectStatus(c,v,m);
 current.declined=false;current.removed=true;current.status='Removed';current.removedAt=new Date().toISOString();current.updatedAt=current.removedAt;
 addProspectTimeline(current,'Removed','Deleted from Declined prospect list');
 c.prospectContacts[key]=current;
 save();renderProspectCentre();
}
function reopenDeclinedProspect(cid,vid,mid){
 const c=db.customers.find(x=>x.id===cid),v=c?.vehicles?.find(x=>x.id===vid),m=v?.maintenance?.find(x=>x.id===mid);if(!c||!v||!m)return;
 saveProspectStatus(c,v,m,{declined:false,contacted:false,responded:false,booked:false,completed:false,snoozed:false,status:'Not contacted',declinedAt:'',declineReason:'',staff:prospectOwner()},'Reopened','Moved back to active prospect list');
}
function renderDeclinedProspects(){
 const rows=declinedProspects();
 return `<div class="card crm-prospect-table-wrap"><div class="crm-declined-head"><div><h3>Declined prospects</h3><p class="muted">Customers who have declined the work. Remove an entry here only when you no longer want it retained in the prospect list.</p></div><strong>${rows.length}</strong></div><table class="crm-due-table crm-prospect-table"><thead><tr><th>Declined</th><th>Customer</th><th>Reg</th><th>Work due</th><th>Reason</th><th>Actions</th></tr></thead><tbody>${rows.map(({c,v,m,st})=>{const key=`${c.id}|${v.id}|${m.id}`;return `<tr><td>${st.declinedAt?new Date(st.declinedAt).toLocaleString('en-GB'):'—'}<small>${esc(st.staff||'')}</small></td><td><strong>${esc(customerName(c))}</strong><small>${esc(c.mobile||c.home||c.work||'No phone')}</small></td><td>${displayReg(v.registration)}</td><td>${esc(m.name)}</td><td>${esc(st.declineReason||'No reason recorded')}</td><td><div class="crm-prospect-actions"><button class="secondary crm-small-btn" data-reopen-declined="${key}">Reopen</button><button class="danger crm-small-btn" data-delete-declined="${key}">Delete from Declined</button><button class="secondary crm-small-btn" data-open-customer="${c.id}">CRM</button></div></td></tr>`}).join('')||`<tr><td colspan="6"><div class="crm-empty"><h3>No declined prospects</h3><p class="muted">Customers marked Declined will appear here.</p></div></td></tr>`}</tbody></table></div>`;
}
function renderProspectReport(){const m=prospectMetrics(),rows=m.booked;const byStaff={};m.rows.forEach(x=>{const n=x.st.staff||'Unassigned';byStaff[n]=byStaff[n]||{contacted:0,booked:0,gp:0};if(x.st.contacted)byStaff[n].contacted++;if(x.st.booked)byStaff[n].booked++;if(x.st.completed)byStaff[n].gp+=Number(x.st.grossProfit||0)});return `<div class="crm-pro-kpi-grid">${[['Customers contacted',m.contacted.length],['Responses',m.responded.length],['Bookings made',m.booked.length],['Booking conversion',pct(m.booked.length,m.contacted.length)+'%'],['Attendance rate',pct(m.completed.length,m.booked.length)+'%'],['Revenue generated',money(m.invoiceValue)],['Operational GP',money(m.gp)],['Average invoice',money(m.completed.length?m.invoiceValue/m.completed.length:0)]].map(x=>`<div class="crm-pro-kpi"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="crm-pro-report-grid"><div class="card"><h3>Booking funnel</h3><div class="crm-funnel">${[['Customers contacted',m.contacted.length],['Customers responded',m.responded.length],['Bookings made',m.booked.length],['Jobs completed',m.completed.length],['Invoices raised',m.completed.filter(x=>Number(x.st.invoiceValue)>0).length]].map((x,i)=>`<div style="--w:${Math.max(18,100-i*14)}%"><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join('')}</div></div><div class="card"><h3>Staff performance</h3><table class="crm-due-table"><thead><tr><th>Staff</th><th>Contacted</th><th>Booked</th><th>Conversion</th><th>GP</th></tr></thead><tbody>${Object.entries(byStaff).map(([name,x])=>`<tr><td>${esc(name)}</td><td>${x.contacted}</td><td>${x.booked}</td><td>${pct(x.booked,x.contacted)}%</td><td>${money(x.gp)}</td></tr>`).join('')||'<tr><td colspan="5">No activity yet</td></tr>'}</tbody></table></div></div><div class="card crm-prospect-table-wrap"><h3>Bookings generated from prospecting</h3><table class="crm-due-table crm-prospect-table"><thead><tr><th>Booked</th><th>Customer</th><th>Registration</th><th>Work booked</th><th>Staff</th><th>Method</th><th>Estimated</th><th>Invoice</th><th>GP</th><th>Status</th></tr></thead><tbody>${rows.map(({c,v,m,st})=>`<tr><td>${st.bookingDate?new Date(st.bookingDate+'T12:00:00').toLocaleDateString('en-GB'):'Not entered'}</td><td><strong>${esc(customerName(c))}</strong><small>${esc(c.id)}</small></td><td>${displayReg(v.registration)}</td><td>${esc(m.name)}</td><td>${esc(st.staff||'Unassigned')}</td><td>${esc(st.contactMethod||'Not recorded')}</td><td>${money(st.bookingValue)}</td><td>${money(st.invoiceValue)}</td><td>${money(st.grossProfit)}</td><td><span class="crm-prospect-badge ${st.completed?'completed':'booked'}">${esc(st.status)}</span></td></tr>`).join('')||`<tr><td colspan="10"><div class="crm-empty"><h3>No prospecting bookings yet</h3><p class="muted">Bookings confirmed from the Prospect Centre will appear here.</p></div></td></tr>`}</tbody></table></div>`}
function renderProspectCentre(){const area=$('crmProspectArea');if(!area)return;const rows=allProspects(prospectWindow),m=prospectMetrics(),due30=allProspects(30).length,due60=allProspects(60).length,due90=allProspects(90).length;area.innerHTML=`<div class="crm-prospect-hero"><div><span class="crm-eyebrow">WAI-102.7 · PROSPECT CENTRE PRO</span><h2>Prospect Centre Pro</h2><p>Turn maintenance reminders into measurable bookings, revenue and operational gross profit.</p></div><div class="crm-window-tabs"><button class="secondary ${prospectView==='pipeline'?'active':''}" data-prospect-view="pipeline">Opportunity pipeline</button><button class="secondary ${prospectView==='declined'?'active':''}" data-prospect-view="declined">Declined (${m.declined.length})</button><button class="secondary ${prospectView==='report'?'active':''}" data-prospect-view="report">Performance report</button><button class="secondary" data-prospect-owner>Staff: ${esc(prospectOwner())}</button></div></div>${prospectView==='report'?renderProspectReport():prospectView==='declined'?renderDeclinedProspects():`<div class="crm-pro-kpi-grid">${[['Due in 30 days',due30],['Due in 60 days',due60],['Due in 90 days',due90],['Bookings made',m.booked.length],['Revenue pipeline',money(m.pipeline)],['Conversion',pct(m.booked.length,m.contacted.length)+'%']].map(x=>`<div class="crm-pro-kpi"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="crm-window-tabs prospect-range-tabs">${[30,60,90].map(d=>`<button class="secondary ${prospectWindow===d?'active':''}" data-prospect-window="${d}">${d} days</button>`).join('')}</div><div class="card crm-prospect-table-wrap"><table class="crm-due-table crm-prospect-table crm-pro-table"><thead><tr><th>Due</th><th>Customer</th><th>Reg</th><th>Work due</th><th>Value</th><th>Status</th><th>Actions</th><th>Timeline</th></tr></thead><tbody>${rows.map(({c,v,m,days})=>{const st=prospectStatus(c,v,m),key=`${c.id}|${v.id}|${m.id}`;return `<tr class="${days<0?'overdue':''}"><td>${new Date(m.nextDueDate+'T12:00:00').toLocaleDateString('en-GB')}<small>${days<0?Math.abs(days)+' days overdue':days+' days'}</small></td><td><strong>${esc(customerName(c))}</strong><small>${esc(c.id)} · ${esc(c.mobile||c.home||c.work||'No phone')}</small></td><td>${displayReg(v.registration)}</td><td><strong>${esc(m.name)}</strong><small>${c.email?esc(c.email):'No email'}</small></td><td>${st.bookingValue?money(st.bookingValue):'—'}</td><td><span class="crm-prospect-badge ${st.completed?'completed':st.booked?'booked':st.responded?'responded':st.declined?'declined':st.snoozed?'snoozed':st.contacted?'contacted':'pending'}">${esc(st.status)}</span>${st.staff?`<small>${esc(st.staff)}</small>`:''}</td><td><div class="crm-prospect-actions"><button class="secondary crm-small-btn" data-call="${key}" ${!(c.mobile||c.home||c.work)?'disabled':''}>Call</button><button class="primary crm-small-btn" data-sms="${key}" ${!c.mobile?'disabled':''}>Text</button><button class="secondary crm-small-btn" data-email="${key}" ${!c.email?'disabled':''}>Email</button><button class="secondary crm-small-btn" data-responded="${key}">Responded</button><button class="secondary crm-small-btn" data-book-diary="${key}">${st.booked?'Edit booking':'Book diary'}</button><button class="secondary crm-small-btn" data-complete="${key}">Completed</button><button class="secondary crm-small-btn" data-decline="${key}">Declined</button><button class="secondary crm-small-btn" data-snooze="${key}">Snooze</button><button class="secondary crm-small-btn" data-open-customer="${c.id}">CRM</button></div></td><td><details class="crm-pro-details"><summary>${(st.timeline||[]).length} event${(st.timeline||[]).length===1?'':'s'}</summary>${renderProspectTimeline(st)}</details></td></tr>`}).join('')||`<tr><td colspan="8"><div class="crm-empty"><h3>No upcoming work</h3><p class="muted">No maintenance items are due within ${prospectWindow} days.</p></div></td></tr>`}</tbody></table></div>`}`;
 area.querySelectorAll('[data-prospect-view]').forEach(b=>b.onclick=()=>{prospectView=b.dataset.prospectView;renderProspectCentre()});
 area.querySelectorAll('[data-prospect-window]').forEach(b=>b.onclick=()=>{prospectWindow=Number(b.dataset.prospectWindow);renderProspectCentre()});
 area.querySelectorAll('[data-prospect-owner]').forEach(b=>b.onclick=setProspectOwner);
 area.querySelectorAll('[data-call]').forEach(b=>b.onclick=()=>callProspect(...b.dataset.call.split('|')));
 area.querySelectorAll('[data-sms]').forEach(b=>b.onclick=()=>sendProspectSMS(...b.dataset.sms.split('|')));
 area.querySelectorAll('[data-email]').forEach(b=>b.onclick=()=>sendProspectEmail(...b.dataset.email.split('|')));
 area.querySelectorAll('[data-responded]').forEach(b=>b.onclick=()=>markProspectResponded(...b.dataset.responded.split('|')));
 area.querySelectorAll('[data-book-diary]').forEach(b=>b.onclick=()=>bookProspectIntoDiary(...b.dataset.bookDiary.split('|')));
 area.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>markProspectCompleted(...b.dataset.complete.split('|')));
 area.querySelectorAll('[data-decline]').forEach(b=>b.onclick=()=>markProspectDeclined(...b.dataset.decline.split('|')));
 area.querySelectorAll('[data-snooze]').forEach(b=>b.onclick=()=>snoozeProspect(...b.dataset.snooze.split('|')));
 area.querySelectorAll('[data-reopen-declined]').forEach(b=>b.onclick=()=>reopenDeclinedProspect(...b.dataset.reopenDeclined.split('|')));
 area.querySelectorAll('[data-delete-declined]').forEach(b=>b.onclick=()=>deleteDeclinedProspect(...b.dataset.deleteDeclined.split('|')));
 area.querySelectorAll('[data-open-customer]').forEach(b=>b.onclick=()=>{selectedId=b.dataset.openCustomer;crmMode='customers';render()})}
function findVehicleByRegistration(reg){let clean=normReg(reg);for(const c of db.customers){for(const v of (c.vehicles||[])){if(normReg(v.registration)===clean)return {customer:c,vehicle:v}}}return null}
function contactNumber(c){return c.mobile||c.home||c.work||''}
function startWorkshopJobFromCustomer(c){
 const vehicles=(c?.vehicles||[]);
 if(!vehicles.length){alert('Please add a vehicle to this CRM customer before creating a workshop job.');return}
 if(vehicles.length===1){loadNewJob(c.id,vehicles[0].id);return}
 modal(`<div class="crm-modal-head"><div><span class="crm-eyebrow">CREATE WORKSHOP JOB</span><h2>Select Vehicle</h2><p>Choose which vehicle to book into the Workshop Diary.</p></div><button id="crmClose">×</button></div><div class="crm-job-vehicle-picker">${vehicles.map(v=>`<button class="crm-job-vehicle-option" data-job-vehicle="${v.id}"><strong>${displayReg(v.registration)}</strong><span>${esc(v.make||'')} ${esc(v.model||'')} ${esc(v.variant||'')}</span><small>${Number(v.mileage||0).toLocaleString('en-GB')} miles</small></button>`).join('')}</div><div class="crm-form-actions"><button class="secondary" id="crmCancel">Cancel</button></div>`);
 $('crmClose').onclick=$('crmCancel').onclick=closeModal;
 document.querySelectorAll('[data-job-vehicle]').forEach(btn=>btn.onclick=()=>{closeModal();loadNewJob(c.id,btn.dataset.jobVehicle)});
}
function loadNewJob(customerId,vehicleId){
 const c=db.customers.find(x=>x.id===customerId),v=c&&(c.vehicles||[]).find(x=>x.id===vehicleId);if(!c||!v)return;
 if(typeof window.show==='function')window.show('diaryScreen');
 const set=(id,value)=>{const e=document.getElementById(id);if(e)e.value=value??''};
 set('reg',displayReg(v.registration));
 set('bookingDate',new Date().toISOString().slice(0,10));
 set('customer',customerName(c));
 set('phone',contactNumber(c));
 set('make',v.make||'');
 set('model',[v.model,v.variant].filter(Boolean).join(' '));
 set('mileage',v.mileage||'');
 let details=[];
 if(c.company)details.push(`Company: ${c.company}`);
 if(c.email)details.push(`Email: ${c.email}`);
 const address=[c.address1,c.town,c.county,c.postcode].filter(Boolean).join(', ');
 if(address)details.push(`Address: ${address}`);
 if(c.preferredContact)details.push(`Preferred contact: ${c.preferredContact}${c.preferredTime?' ('+c.preferredTime+')':''}`);
 if((c.preferences||[]).length)details.push('Preferences: '+c.preferences.join(', '));
 if(c.notes)details.push('Customer note: '+c.notes);
 details.push(`CRM: ${c.id} · ${loyalty(c)} customer · Health ${customerHealth(c)}%`);
 set('specialInstructions',details.join('\n'));
 window.__wai096LoadedCRM={
   customerId:c.id,vehicleId:v.id,customerLoyalty:loyalty(c),customerHealth:customerHealth(c),
   preferredContact:c.preferredContact||'',email:c.email||'',address,
   company:c.company||'',mobile:c.mobile||'',home:c.home||'',work:c.work||''
 };
 document.getElementById('reg')?.dispatchEvent(new Event('input',{bubbles:true}));
 document.getElementById('diaryScreen')?.scrollIntoView({behavior:'smooth',block:'start'});
 setTimeout(()=>document.getElementById('workRequired')?.focus(),150);
}
function recordJobCreated(job){
 if(!job?.customerId||!job?.vehicleId)return;
 const c=db.customers.find(x=>x.id===job.customerId),v=c&&(c.vehicles||[]).find(x=>x.id===job.vehicleId);
 if(!c||!v)return;
 c.timeline=c.timeline||[];
 v.lifeStory=v.lifeStory||[];
 const exists=c.timeline.some(x=>x.jobId===job.id);
 if(!exists){
   const event={date:job.createdAt||new Date().toISOString(),title:`Workshop job created · ${displayReg(v.registration)}`,detail:`${job.jobNo||''}${job.workRequired?' · '+job.workRequired:''}`,jobId:job.id};
   c.timeline.push(event);
   v.lifeStory.push({...event});
   c.visitCount=Number(c.visitCount||0)+1;
   save();
 }
}
function openMaintenance(customerId,vehicleId){selectedId=customerId;activeTab='maintenance';if(typeof window.show==='function')window.show('crmScreen');render();setTimeout(()=>{document.querySelector(`[data-maint^="${vehicleId}|"]`)?.scrollIntoView({behavior:'smooth',block:'center'})},50)}
window.WorkshopCRMBridge={findVehicleByRegistration,loadNewJob,startWorkshopJobFromCustomer,recordJobCreated,syncFinancialsFromInvoices,openMaintenance,openMaintenanceForVehicle:(vehicleId)=>{const c=db.customers.find(x=>(x.vehicles||[]).some(v=>v.id===vehicleId));if(c){selectedId=c.id;activeTab='maintenance';crmMode='customers';render()}},getLoaded:()=>window.__wai096LoadedCRM||null,clearLoaded:()=>{window.__wai096LoadedCRM=null}};
function init(){if(!$('crmScreen'))return;syncFinancialsFromInvoices();$('crmCustomersTab').onclick=()=>{crmMode='customers';render()};$('crmProspectsTab').onclick=()=>{crmMode='prospects';render()};$('crmNewCustomerBtn').onclick=()=>openCustomerModal();$('crmDataIntegrityBtn').onclick=dataIntegrity;$('crmRefresh').onclick=render;$('crmSearch').oninput=renderList;$('crmFilter').onchange=renderList;render();window.renderWAI096CRM=render}
window.addEventListener('wai-finance-updated',()=>{syncFinancialsFromInvoices();render()});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
